// GENERATED by scripts/sync-legal.mjs. Edit packages/shared/src/legal, then re-run the script.
// Shape of every StreetdocMD legal document rendered in the apps and on the landing page.
// This folder is the source of truth; `node scripts/sync-legal.mjs` copies it into the
// apps that can't import @streetdocmd/shared on Vercel (landing-page, patient-web).

export type LegalBlock =
  | { kind: "p"; text: string }
  /** a numbered clause, e.g. num "1.1" */
  | { kind: "clause"; num: string; text: string }
  | { kind: "bullets"; items: string[] }
  | { kind: "table"; headers: string[]; rows: string[][] }
  /** a boxed notice, e.g. "Not an emergency service" */
  | { kind: "callout"; title?: string; text: string };

export interface LegalSection {
  id: string;
  title: string;
  blocks: LegalBlock[];
}

export interface LegalDocument {
  slug: "privacy-policy" | "patient-terms" | "provider-agreement" | "facility-agreement";
  title: string;
  subtitle: string;
  /** the version recorded with every acceptance */
  version: string;
  versionLabel: string;
  partyLine?: string;
  intro: LegalBlock[];
  sections: LegalSection[];
  /** exact wording of the unchecked acceptance box(es) the document prescribes */
  acceptanceLabels: string[];
}
